import {mkdir,writeFile} from 'node:fs/promises';
import {catalogueWorks,catalogueCollections} from '../src/data/collection-catalogue.js';
const q=value=>value==null?'null':typeof value==='boolean'?String(value):typeof value==='number'?String(value):`'${String(value).replaceAll("'","''")}'`;
const sql=[`-- Verified public catalogue only; no library, reading-status, recommendation or taste writes.
-- Generated by scripts/generate-collection-seed.mjs; inspect before applying.
-- Abort on a conflicting key. Never overwrite a pre-existing catalogue.
`];
for(const work of catalogueWorks) sql.push(`insert into public.collection_catalogue_books(key,title,authors,publication_year,publication_state,format,source_url,verified_at)
values(${[work.key,work.title,work.authors,work.publication_year,work.publication_state||'published',work.format,work.source_url,'2026-10-20'].map(q).join(',')});`);
// Exact title and ordered author match only; ambiguous matches remain unlinked.
sql.push(`update public.collection_catalogue_books c set book_id=matches.id from (
  select c.key,min(b.id::text)::uuid id from public.collection_catalogue_books c join public.books b on lower(trim(b.title))=lower(trim(c.title))
  where c.book_id is null and c.authors=(select string_agg(a.name,', ' order by ba.author_order) from public.book_authors ba join public.authors a on a.id=ba.author_id where ba.book_id=b.id)
  group by c.key having count(*)=1
) matches where c.key=matches.key and c.book_id is null;`);
for(const collection of catalogueCollections) {
  if(collection.kind==='series') sql.push(`insert into public.series(name) values(${q(collection.name)}) on conflict(name) do nothing;`);
  sql.push(`insert into public.collections(key,name,kind,description,complete,source_url,series_id) values(${[collection.key,collection.name,collection.kind,collection.description,collection.complete,collection.source_url].map(q).join(',')},${collection.kind==='series'?`(select id from public.series where name=${q(collection.name)})`:'null'});`);
  for(const member of collection.members) sql.push(`insert into public.collection_memberships(collection_key,work_key,official_number) values(${[collection.key,member.work_key,member.official_number].map(q).join(',')});`);
}
sql.push(`-- Reuse existing official memberships, preserving any recorded conflicts for review.
insert into public.book_series(book_id,series_id,series_order)
select b.book_id,c.series_id,m.official_number from public.collection_memberships m
join public.collections c on c.key=m.collection_key
join public.collection_catalogue_books b on b.key=m.work_key
where c.series_id is not null and b.book_id is not null
on conflict(book_id,series_id) do nothing;`);
await mkdir('supabase/seeds',{recursive:true});
await writeFile('supabase/seeds/collections-verified.sql',sql.join('\n\n')+'\n');
await writeFile('docs/collection-catalogue.json',JSON.stringify({verified_at:'2026-10-20',works:catalogueWorks,collections:catalogueCollections},null,2)+'\n');
console.log(`${catalogueWorks.length} unique works, ${catalogueCollections.length} collections. Seed generated; not applied.`);
